import os, glob, re, json

d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read()
lines = t.split('\n')

# Look for input/output data in the logs
for i, line in enumerate(lines[:50]):
    try:
        entry = json.loads(line)
        if 'input' in entry:
            print(f"\nFound at line {i}:")
            print(f"Type: {entry.get('type')}")
            for k, v in entry.items():
                if k in ['input', 'output', 'Task input', 'Test input']:
                    print(f"  {k}: type={type(v)}")
    except json.JSONDecodeError:
        pass
